package com.elogistic.backend.merchant.internal.infrastructure;

import com.elogistic.backend.merchant.api.customer.MerchantFacilities;
import com.elogistic.backend.merchant.api.customer.MerchantFacilities.*;
import com.elogistic.backend.merchant.internal.application.port.MerchantFingerprints;
import com.elogistic.backend.merchant.internal.domain.FacilityInput;
import static com.elogistic.backend.merchant.internal.domain.OrganizationContactInput.text;
import java.security.MessageDigest;
import java.sql.Timestamp;
import java.time.*;
import java.time.temporal.ChronoUnit;
import java.util.*;
import javax.sql.DataSource;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.support.TransactionSynchronizationManager;
import tools.jackson.databind.JsonNode;
import tools.jackson.databind.json.JsonMapper;

/** Current Identity -> Merchant lock and same physical transaction for every command. */
public final class JdbcMerchantFacilities implements MerchantFacilities {
    private static final JsonMapper JSON=JsonMapper.builder().build();
    private final DataSource source;private final JdbcTemplate jdbc;private final MerchantFingerprints hashes;private final Clock clock;private final boolean enabled;
    public JdbcMerchantFacilities(DataSource source,MerchantFingerprints hashes,Clock clock,boolean enabled){this.source=source;this.jdbc=new JdbcTemplate(source);this.hashes=hashes;this.clock=clock;this.enabled=enabled;}
    private static Failure fail(String code){return new Failure(code);}
    UUID org(Access a){a.requireCurrent();if(!enabled)throw fail("BUSINESS_DISABLED");if(!TransactionSynchronizationManager.isActualTransactionActive()||!TransactionSynchronizationManager.hasResource(source))throw new IllegalStateException("FACILITY_ADMISSION_REQUIRED");return a.scope().context().organizationId();}
    void permit(Access a,String right,UUID site){org(a);if(!a.scope().permits("facility.read",site)||!a.scope().permits(right,site))throw fail("RESOURCE_NOT_FOUND");}
    private Instant now(){return clock.instant().truncatedTo(ChronoUnit.MICROS);}
    private static String str(JsonNode n,String k){var v=n.get(k);return v==null||v.isNull()?null:v.asString();}
    private static UUID id(JsonNode n,String k){String v=str(n,k);return v==null?null:UUID.fromString(v);}
    private static Instant instant(JsonNode n,String k){String v=str(n,k);return v==null?null:OffsetDateTime.parse(v.replace(' ','T')).toInstant();}
    private static <T>T value(JsonNode n,String k,Class<T> type){var v=n.get(k);return v==null||v.isNull()?null:JSON.treeToValue(v,type);}
    private Facility decode(Access a,String raw){var v=JSON.readTree(raw);UUID site=id(v,"id");permit(a,"facility.read",site);var actions=new ArrayList<String>();if("ACTIVE".equals(str(v,"state"))&&a.scope().permits("facility.manage",site))actions.addAll(List.of("UPDATE","ARCHIVE","RESPONSIBILITY"));if("ACTIVE".equals(str(v,"state"))&&a.scope().permits("defaults.manage",null))actions.add("SET_DEFAULT");if("ACTIVE".equals(str(v,"state"))&&a.scope().permits("shipment.draft.read",site)){
            if(a.scope().permits("shipment.draft.write",site))actions.add("CREATE_DRAFT");
            if(a.scope().permits("shipment.draft.write",site)&&a.scope().permits("shipment.import",site))actions.add("IMPORT_DRAFTS");
            if(a.scope().permits("shipment.prepare",site))actions.add("READ_PREPARATION");
            if(a.scope().permits("shipment.prepare",site)&&responsible(a,site,"PREPARATION"))actions.add("PREPARE_PARCELS");
            if(a.scope().permits("shipment.handover.read",site))actions.add("READ_HANDOVER");
            if(a.scope().permits("shipment.handover.read",site)&&a.scope().permits("shipment.handover.manage",site)&&responsible(a,site,"HANDOVER"))actions.add("MANAGE_HANDOVER");
        }return new Facility(site,id(v,"organization_id"),str(v,"name"),value(v,"contact",Contact.class),str(v,"state"),v.get("version").asLong(),instant(v,"created_at"),instant(v,"updated_at"),str(v,"code"),str(v,"kind"),value(v,"sender_contact",Contact.class),value(v,"return_contact",Contact.class),value(v,"operating_hours",Hours.class),actions);}
    private boolean responsible(Access a,UUID site,String kind){return a.scope().permits("facility.manage",site)&&a.scope().permits("facility.read",site)||jdbc.queryForObject("SELECT count(*) FROM merchant.facility_responsibility WHERE facility_id=? AND responsibility=?",Integer.class,site,kind)==0||jdbc.queryForObject("SELECT count(*) FROM merchant.facility_responsibility WHERE facility_id=? AND responsibility=? AND account_id=?",Integer.class,site,kind,a.actorAccountId())>0;}
    @Override public Facility get(Access a,UUID site){var rows=jdbc.query("SELECT to_jsonb(f)::text FROM merchant.facility f WHERE organization_id=? AND id=?",(r,n)->r.getString(1),org(a),site);if(rows.size()!=1)throw fail("RESOURCE_NOT_FOUND");return decode(a,rows.getFirst());}
    private String visibility(Access a,List<Object> args){args.add(org(a));if(a.scope().permits("facility.read",null))return "f.organization_id=?";var sites=a.scope().facilities("facility.read");if(sites.isEmpty())throw fail("RESOURCE_NOT_FOUND");args.addAll(sites);return "f.organization_id=? AND f.id IN ("+String.join(",",Collections.nCopies(sites.size(),"?"))+")";}
    @Override public Page list(Access a,Query q){
        if(q==null||q.page()<0||q.size()!=20||q.state()!=null&&!Set.of("ACTIVE","ARCHIVED").contains(q.state())||q.kind()!=null&&!FacilityInput.KINDS.contains(q.kind()))throw fail("VALIDATION_FAILED");
        List<Object> args=new ArrayList<>();String where=visibility(a,args)+" AND f.state=?";args.add(q.state()==null?"ACTIVE":q.state());
        if(q.kind()!=null){where+=" AND f.kind=?";args.add(q.kind());}
        if(q.code()!=null){if(!q.code().matches("[A-Z0-9_-]{1,40}"))throw fail("VALIDATION_FAILED");where+=" AND f.code=?";args.add(q.code());}
        if(q.search()!=null){String search;try{search=text(q.search(),160);}catch(RuntimeException bad){throw fail("VALIDATION_FAILED");}where+=" AND lower(concat_ws(' ',f.name,f.code,f.contact->>'name',f.contact->>'phone',f.contact->'address'->>'addressLine',f.contact->'address'->>'locality',f.contact->'address'->>'administrativeArea')) LIKE ? ESCAPE '!'";args.add("%"+search.toLowerCase(Locale.ROOT).replace("!","!!").replace("%","!%").replace("_","!_")+"%");}
        args.add(Math.multiplyExact((long)q.page(),20));var rows=jdbc.query("SELECT to_jsonb(f)::text FROM merchant.facility f WHERE "+where+" ORDER BY f.updated_at DESC,f.id LIMIT 21 OFFSET ?",(r,n)->decode(a,r.getString(1)),args.toArray());return new Page(rows.stream().limit(20).toList(),q.page(),20,rows.size()>20);
    }
    record Prior(UUID target,UUID facility,String kind,long expected,long result,String keyId,byte[] fingerprint){}
    private Optional<Prior> prior(Access a,String op,UUID key){return jdbc.query("SELECT target_id,facility_id,resource_kind,expected_version,result_version,fingerprint_key_id,fingerprint FROM merchant.facility_command_receipt WHERE organization_id=? AND actor_account_id=? AND operation=? AND operation_key=?",(r,n)->new Prior(r.getObject(1,UUID.class),r.getObject(2,UUID.class),r.getString(3),r.getLong(4),r.getLong(5),r.getString(6),r.getBytes(7)),org(a),a.actorAccountId(),op,key).stream().findFirst();}
    private byte[] hash(Access a,String keyId,String op,UUID target,long version,String payload){return hashes.hash(keyId,"merchantFacility"+op,target,version,org(a).toString(),a.actorAccountId().toString(),payload);}
    private String snapshot(String kind,UUID target,long version){return jdbc.queryForObject("SELECT snapshot::text FROM merchant.facility_version WHERE resource_kind=? AND target_id=? AND version=?",String.class,kind,target,version);}
    private void commandPermission(Access a,String op,UUID site){if(op.equals("DEFAULT")){org(a);if(!a.scope().permits("defaults.manage",null))throw fail("RESOURCE_NOT_FOUND");if(site!=null)permit(a,"facility.read",site);}else{permit(a,"facility.manage",op.equals("CREATE")?null:site);}}
    private String replay(Access a,String op,UUID target,long expected,String payload,Prior p){commandPermission(a,op,p.facility());byte[] h=hash(a,p.keyId(),op,target,expected,payload);try{if(!p.target().equals(target)||p.expected()!=expected||!MessageDigest.isEqual(h,p.fingerprint()))throw fail("IDEMPOTENCY_CONFLICT");}finally{Arrays.fill(h,(byte)0);Arrays.fill(p.fingerprint(),(byte)0);}return snapshot(p.kind(),p.target(),p.result());}
    private void evidence(Access a,String op,UUID key,String kind,UUID target,UUID facility,long expected,Instant stamp,String payload){
        jdbc.update("INSERT INTO merchant.facility_version(resource_kind,target_id,organization_id,version,snapshot) VALUES(?,?,?,?,merchant.facility_snapshot(?,?))",kind,target,org(a),expected+1,kind,target);
        String keyId=hashes.activeKey();byte[] h=hash(a,keyId,op,target,expected,payload);
        try{jdbc.update("INSERT INTO merchant.facility_command_receipt VALUES(?,?,?,?,?,?,?,?,?,?,?,?)",org(a),a.actorAccountId(),op,key,kind,target,facility,expected,expected+1,keyId,h,Timestamp.from(stamp));}finally{Arrays.fill(h,(byte)0);}
        jdbc.update("INSERT INTO merchant.facility_audit VALUES(?,?,?,?,?,?,?,?,?,?,?)",UUID.randomUUID(),org(a),a.actorAccountId(),op,key,kind,target,expected,expected+1,a.requestId(),Timestamp.from(stamp));a.meaningfulAction();a.requireCurrent();
    }
    private Input valid(Input v){try{return FacilityInput.normalize(v);}catch(RuntimeException bad){throw fail("VALIDATION_FAILED");}}
    private void codeAvailable(Access a,String code,UUID excluded){if(jdbc.queryForObject("SELECT count(*) FROM merchant.facility WHERE organization_id=? AND code=? AND id<>?",Integer.class,org(a),code,excluded)>0)throw fail("FACILITY_CODE_CONFLICT");}
    @Override public Facility create(Access a,Input supplied,UUID key){Input in=valid(supplied);commandPermission(a,"CREATE",null);String payload=JSON.writeValueAsString(in);var old=prior(a,"CREATE",key);if(old.isPresent())return decode(a,replay(a,"CREATE",old.get().target(),0,payload,old.get()));UUID target=UUID.randomUUID();codeAvailable(a,in.code(),target);Instant stamp=now();
        jdbc.update("INSERT INTO merchant.facility(id,organization_id,name,contact,state,version,created_at,updated_at,code,kind,sender_contact,return_contact,operating_hours) VALUES(?,?,?,?::jsonb,'ACTIVE',1,?,?,?,?,?::jsonb,?::jsonb,?::jsonb)",target,org(a),in.name(),JSON.writeValueAsString(in.contact()),Timestamp.from(stamp),Timestamp.from(stamp),in.code(),in.kind(),json(in.senderContact()),json(in.returnContact()),json(in.operatingHours()));evidence(a,"CREATE",key,"SITE",target,target,0,stamp,payload);return get(a,target);
    }
    private static String json(Object v){return v==null?null:JSON.writeValueAsString(v);}
    @Override public Facility update(Access a,UUID target,Input supplied,long expected,UUID key){Input in=valid(supplied);var before=get(a,target);commandPermission(a,"UPDATE",target);String payload=JSON.writeValueAsString(in);var old=prior(a,"UPDATE",key);if(old.isPresent())return decode(a,replay(a,"UPDATE",target,expected,payload,old.get()));if(before.version()!=expected)throw fail("PRECONDITION_STALE");if(!before.state().equals("ACTIVE"))throw fail("FACILITY_STATE_CONFLICT");if(before.code()!=null&&!before.code().equals(in.code()))throw fail("FACILITY_CODE_IMMUTABLE");codeAvailable(a,in.code(),target);Instant stamp=now();
        jdbc.update("UPDATE merchant.facility SET name=?,contact=?::jsonb,code=?,kind=?,sender_contact=?::jsonb,return_contact=?::jsonb,operating_hours=?::jsonb,version=version+1,updated_at=? WHERE id=? AND organization_id=? AND version=?",in.name(),json(in.contact()),in.code(),in.kind(),json(in.senderContact()),json(in.returnContact()),json(in.operatingHours()),Timestamp.from(stamp),target,org(a),expected);evidence(a,"UPDATE",key,"SITE",target,target,expected,stamp,payload);return get(a,target);
    }
    @Override public Facility archive(Access a,UUID target,long expected,UUID key){var before=get(a,target);commandPermission(a,"ARCHIVE",target);var old=prior(a,"ARCHIVE",key);if(old.isPresent())return decode(a,replay(a,"ARCHIVE",target,expected,null,old.get()));if(before.version()!=expected)throw fail("PRECONDITION_STALE");if(!before.state().equals("ACTIVE"))throw fail("FACILITY_STATE_CONFLICT");if(Boolean.TRUE.equals(jdbc.queryForObject("SELECT merchant.facility_has_work(?,?)",Boolean.class,org(a),target)))throw fail("FACILITY_REFERENCED");Instant stamp=now();jdbc.update("UPDATE merchant.facility SET state='ARCHIVED',version=version+1,updated_at=? WHERE id=? AND organization_id=? AND version=?",Timestamp.from(stamp),target,org(a),expected);evidence(a,"ARCHIVE",key,"SITE",target,target,expected,stamp,null);return get(a,target);}
    private static Default defaultOf(String raw){var v=JSON.readTree(raw);return new Default(id(v,"facility_id"),v.get("version").asLong(),instant(v,"updated_at"));}
    @Override public Default defaultFacility(Access a){UUID org=org(a);var rows=jdbc.query("SELECT to_jsonb(d)::text FROM merchant.facility_default d WHERE id=?",(r,n)->r.getString(1),org);if(!a.scope().permits("defaults.manage",null)&&!a.scope().permits("facility.read",null)&&a.scope().facilities("facility.read").isEmpty())throw fail("RESOURCE_NOT_FOUND");if(rows.isEmpty())return new Default(null,0,null);var d=defaultOf(rows.getFirst());if(d.facilityId()!=null)permit(a,"facility.read",d.facilityId());return d;}
    @Override public Default setDefault(Access a,UUID facility,long expected,UUID key){commandPermission(a,"DEFAULT",facility);String payload=json(facility);var old=prior(a,"DEFAULT",key);if(old.isPresent())return defaultOf(replay(a,"DEFAULT",org(a),expected,payload,old.get()));if(facility!=null)a.scope().requireActiveFacility(facility);var current=defaultFacility(a);if(current.version()!=expected)throw fail("PRECONDITION_STALE");Instant stamp=now();jdbc.update("INSERT INTO merchant.facility_default VALUES(?,?,1,?) ON CONFLICT(id) DO UPDATE SET facility_id=excluded.facility_id,version=merchant.facility_default.version+1,updated_at=excluded.updated_at",org(a),facility,Timestamp.from(stamp));evidence(a,"DEFAULT",key,"DEFAULT",org(a),facility,expected,stamp,payload);return defaultFacility(a);}
    private static Responsibilities teamOf(String raw){var v=JSON.readTree(raw);return new Responsibilities(id(v,"id"),Arrays.asList(JSON.treeToValue(v.get("items"),Responsibility[].class)),v.get("version").asLong(),instant(v,"updated_at"));}
    @Override public Responsibilities responsibilities(Access a,UUID target){get(a,target);var rows=jdbc.query("SELECT merchant.facility_team_snapshot(id)::text FROM merchant.facility_team WHERE organization_id=? AND id=?",(r,n)->r.getString(1),org(a),target);return rows.isEmpty()?new Responsibilities(target,List.of(),0,null):teamOf(rows.getFirst());}
    @Override public Responsibilities setResponsibilities(Access a,UUID target,List<Responsibility> supplied,long expected,UUID key){get(a,target);commandPermission(a,"RESPONSIBILITY",target);if(supplied==null||supplied.size()>30||supplied.stream().anyMatch(i->i==null||i.accountId()==null||!Set.of("PREPARATION","HANDOVER","RETURNS").contains(i.responsibility()))||new HashSet<>(supplied).size()!=supplied.size())throw fail("VALIDATION_FAILED");var items=supplied.stream().sorted(Comparator.comparing((Responsibility i)->i.accountId().toString()).thenComparing(Responsibility::responsibility)).toList();String payload=json(items);var old=prior(a,"RESPONSIBILITY",key);if(old.isPresent())return teamOf(replay(a,"RESPONSIBILITY",target,expected,payload,old.get()));a.scope().requireActiveFacility(target);for(var i:items)if(!a.scope().eligibleFacilityMember(i.accountId(),target))throw fail("FACILITY_MEMBER_UNAVAILABLE");if(responsibilities(a,target).version()!=expected)throw fail("PRECONDITION_STALE");Instant stamp=now();jdbc.update("INSERT INTO merchant.facility_team VALUES(?,?,1,?) ON CONFLICT(id) DO UPDATE SET version=merchant.facility_team.version+1,updated_at=excluded.updated_at",target,org(a),Timestamp.from(stamp));jdbc.update("DELETE FROM merchant.facility_responsibility WHERE organization_id=? AND facility_id=?",org(a),target);for(var i:items)jdbc.update("INSERT INTO merchant.facility_responsibility VALUES(?,?,?,?)",target,org(a),i.accountId(),i.responsibility());evidence(a,"RESPONSIBILITY",key,"TEAM",target,target,expected,stamp,payload);return responsibilities(a,target);}
    @Override public Receipt receipt(Access a,String op,UUID key){if(!Set.of("CREATE","UPDATE","ARCHIVE","DEFAULT","RESPONSIBILITY").contains(op))throw fail("RESOURCE_NOT_FOUND");var p=prior(a,op,key).orElseThrow(()->fail("RESOURCE_NOT_FOUND"));commandPermission(a,op,p.facility());if(!op.equals("DEFAULT"))get(a,p.target());return new Receipt(op,p.target(),"COMMITTED",p.result());}
}
